29	    @Mapping(target = "membershipPoints",
30	        expression = "java(org.springframework.samples.petclinic.mapper.MembershipLevelResolver.deriveMembershipPoints(owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdMemberCount(), owner.getRegistrationDate()))")
31	    @Mapping(target = "membershipLevel",
32	        expression = "java(org.springframework.samples.petclinic.mapper.MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdMemberCount(), owner.getRegistrationDate()))")
33	    @Mapping(target = "locality",
34	        expression = "java(org.springframework.samples.petclinic.mapper.LocalityResolver.deriveLocality(owner.getCustomerCode()))")
35	    @Mapping(target = "timezone",
36	        expression = "java(org.springframework.samples.petclinic.mapper.TimezoneResolver.deriveTimezone(owner.getCustomerCode()))")
37	    @Mapping(target = "bulkSignupWarning",
38	        expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
39	    @Mapping(target = "telephoneDisplay",
40	        expression = "java(org.springframework.samples.petclinic.mapper.TelephoneDisplayResolver.deriveTelephoneDisplay(owner.getTelephone()))")
41	    @Mapping(target = "contactPreference",
42	        expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
43	    @Mapping(target = "ageBand",
44	        expression = "java(org.springframework.samples.petclinic.mapper.AgeBandResolver.deriveAgeBand(owner.getBirthDate(), owner.getRegistrationDate()))")
45	    @Mapping(target = "sharesHousehold", ignore = true)
46	    @Mapping(target = "identityKey", ignore = true)
47	    OwnerDto toOwnerDto(Owner owner);
48	
49	    Owner toOwner(OwnerDto ownerDto);
50	
51	    @Mapping(target = "id", ignore = true)
52	    @Mapping(target = "pets", ignore = true)
53	    Owner toOwner(OwnerFieldsDto ownerDto);
54	
55	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
56	
57	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
58	
59	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
60	        OwnerPageDto ownerPageDto = new OwnerPageDto();
61	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
62	        ownerPageDto.setPage(ownerPage.getNumber());
