136	 */
137	
138	@RestController
139	@CrossOrigin(exposedHeaders = "errors, content-type")
140	@RequestMapping("/api")
141	public class OwnerRestControllerV1 implements OwnersApi {
142	
143	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
144	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
145	
146	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
147	    private static final int MAX_OWNERS_PER_CITY = 50;
148	
149	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
150	    private static final int MAX_OWNERS_PER_DAY = 100;
151	
152	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
153	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
154	
155	    private final ClinicService clinicService;
156	
157	    private final OwnerMapper ownerMapper;
158	
159	    private final PetMapper petMapper;
160	
161	    private final VisitMapper visitMapper;
162	
163	    private final TelephoneNormalizer telephoneNormalizer;
164	
165	    private final AddressNormalizer addressNormalizer;
166	
167	    private final EmailNormalizer emailNormalizer;
168	
169	    private final IdentityKeyResolver identityKeyResolver;
170	
171	    private final HouseholdResolver householdResolver;
172	
173	    public OwnerRestControllerV1(ClinicService clinicService,
174	                                 OwnerMapper ownerMapper,
175	                                 PetMapper petMapper,
176	                                 VisitMapper visitMapper,
177	                                 TelephoneNormalizer telephoneNormalizer,
178	                                 AddressNormalizer addressNormalizer,
179	                                 EmailNormalizer emailNormalizer,
180	                                 IdentityKeyResolver identityKeyResolver,
181	                                 HouseholdResolver householdResolver) {
182	        this.clinicService = clinicService;
183	        this.ownerMapper = ownerMapper;
184	        this.petMapper = petMapper;
185	        this.visitMapper = visitMapper;
186	        this.telephoneNormalizer = telephoneNormalizer;
187	        this.addressNormalizer = addressNormalizer;
188	        this.emailNormalizer = emailNormalizer;
189	        this.identityKeyResolver = identityKeyResolver;
190	        this.householdResolver = householdResolver;
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
196	        Collection<Owner> owners;
197	        if (lastName != null) {
198	            owners = this.clinicService.findOwnerByLastName(lastName);
199	        } else {
200	            owners = this.clinicService.findAllOwners();
201	        }
202	        if (owners.isEmpty()) {
203	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	        }
205	        owners.forEach(this::populateHouseholdMemberCount);
206	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
207	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
213	        Owner owner = this.clinicService.findOwnerById(ownerId);
214	        if (owner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        populateHouseholdMemberCount(owner);
218	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
219	    }
220	
221	    /**
222	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
223	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
224	     * by the mapper alone.
225	     *
226	     * @param owner the owner to map
227	     * @return the owner DTO carrying its identity key
228	     */
229	    private OwnerDto toOwnerDto(Owner owner) {
230	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
231	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
232	        return ownerDto;
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Transactional
237	    @Override
238	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
239	        normalizeAndValidate(ownerFieldsDto);
240	        HttpHeaders headers = new HttpHeaders();
241	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
242	        populateDerivedFields(owner, ownerFieldsDto);
243	        requireUniqueIdentity(owner);
244	        requireHouseholdNotDuplicate(owner, ownerFieldsDto);
245	        flagPossibleDuplicate(owner, ownerFieldsDto);
246	        this.clinicService.saveOwner(owner);
247	        populateHouseholdMemberCount(owner);
248	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
249	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
250	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount(),
251	                owner.getHouseholdMemberCount(), owner.getRegistrationDate()),
252	            owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100));
253	        OwnerDto ownerDto = toOwnerDto(owner);
254	        headers.setLocation(UriComponentsBuilder.newInstance()
255	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
256	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
257	    }
258	
259	    /**
260	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
261	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
262	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
263	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
264	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
265	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
266	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
267	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
268	     *
269	     * @param owner          the newly mapped owner about to be saved
270	     * @param ownerFieldsDto the incoming owner payload
271	     */
272	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
273	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
274	        owner.setNamesakeCount(countNamesakes(owner));
275	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
276	        assignHouseholdId(owner);
277	    }
278	
279	    /**
280	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
281	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
282	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
283	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
284	     * that predate this create; distinct owners therefore always receive distinct customer codes.
285	     *
286	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
287	     * @return the de-duplicated customer code, unique across all existing owners
288	     */
289	    private String deriveUniqueCustomerCode(Owner owner) {
290	        String base = identityKeyResolver.deriveCustomerCode(owner);
291	        Collection<Owner> existing = this.clinicService.findAllOwners();
292	        String candidate = base;
293	        int n = 2;
294	        while (isCustomerCodeInUse(candidate, existing)) {
295	            candidate = base + "-" + n;
296	            n++;
297	        }
298	        return candidate;
299	    }
300	
301	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
302	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
303	    }
304	
305	    /**
306	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
307	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
308	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
309	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
310	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
311	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
312	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
313	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
314	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
315	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
316	     * assigned (see {@link #requireUniqueIdentity}).
317	     *
318	     * @param ownerFieldsDto the incoming owner payload, mutated in place
319	     * @throws MissingOwnerFieldsException if any required field is missing or blank
320	     */
321	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
322	        normalizeAddress(ownerFieldsDto);
323	        validateRequiredFields(ownerFieldsDto);
324	        validatePostcode(ownerFieldsDto);
325	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
326	        ownerFieldsDto.setTelephone(telephone);
327	        requireCityHasCapacity(ownerFieldsDto.getCity());
328	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
329	        ownerFieldsDto.setRegistrationDate(registrationDate);
330	        requireDailyLimitNotReached(registrationDate);
331	        normalizeEmail(ownerFieldsDto);
332	    }
333	
334	    /**
335	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
336	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
337	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
338	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
339	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
340	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
341	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
342	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
343	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
344	     *
345	     * @param ownerFieldsDto the incoming owner payload, mutated in place
346	     */
347	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
348	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
349	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
350	        if (!line1.isEmpty()) {
351	            ownerFieldsDto.setAddressLine1(line1);
352	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
353	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
354	        }
355	        else {
356	            ownerFieldsDto.setAddressLine1(null);
357	            ownerFieldsDto.setAddressLine2(null);
358	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
359	        }
360	    }
361	
362	    /**
363	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
364	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
365	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
366	     * place so the caller can map and save it directly.
367	     *
368	     * @param ownerFieldsDto the incoming owner payload, mutated in place
369	     */
370	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
371	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
372	    }
373	
374	    /**
375	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
376	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
377	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
378	     * later than the current server date is rejected.
379	     *
380	     * @param ownerFieldsDto the incoming owner payload
381	     * @return the effective registration date rolled forward onto a business day
382	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
383	     */
384	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
385	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
386	        if (effective == null) {
387	            effective = LocalDate.now();
388	        }
389	        else if (effective.isAfter(LocalDate.now())) {
390	            throw new FutureRegistrationDateException(
391	                "the registration date must not be later than the current server date");
392	        }
393	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
394	            effective = effective.plusDays(1);
395	        }
396	        return effective;
397	    }
398	
399	    /**
400	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
401	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
402	     * further owner may be created for that day.
403	     *
404	     * @param registrationDate the adjusted business-day registration date of the owner being created
405	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
406	     */
407	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
408	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
409	            throw new DailyOwnerLimitExceededException(
410	                "the maximum number of owners for today has already been reached");
411	        }
412	    }
413	
414	    /**
415	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
416	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
417	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
418	     * warning threshold) so both express the same per-day count in one place.
419	     *
420	     * @param registrationDate the adjusted business-day registration date to count owners for
421	     * @return the number of existing owners registered on that day
422	     */
423	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
424	        return this.clinicService.findAllOwners().stream()
425	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
426	            .count();
427	    }
428	
429	    /**
430	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
431	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
432	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
433	     * reflects only owners that predate it.
434	     *
435	     * @param registrationDate the adjusted business-day registration date of the owner being created
436	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
437	     */
438	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
439	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
440	    }
441	
442	    /**
443	     * Counts how many existing owners already share the given owner's first and last name, compared
444	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
445	     * create; it is zero when the owner's name is unique.
446	     *
447	     * @param owner the newly mapped owner about to be saved
448	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
449	     */
450	    private int countNamesakes(Owner owner) {
451	        String firstName = owner.getFirstName();
452	        String lastName = owner.getLastName();
453	        return (int) this.clinicService.findAllOwners().stream()
454	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
455	                && lastName.equalsIgnoreCase(existing.getLastName()))
456	            .count();
457	    }
458	
459	    /**
460	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
461	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
462	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
463	     *
464	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
465	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
466	     * flat {@code address}.
467	     *
468	     * @param ownerFieldsDto the owner payload to validate
469	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
470	     */
471	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
472	        List<String> missingFields = new ArrayList<>();
473	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
474	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
475	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
476	        requireText(missingFields, "city", ownerFieldsDto.getCity());
477	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
478	        if (!missingFields.isEmpty()) {
479	            throw new MissingOwnerFieldsException(missingFields);
480	        }
481	    }
482	
483	    private void requireText(List<String> missingFields, String fieldName, String value) {
484	        if (value == null || value.isBlank()) {
485	            missingFields.add(fieldName);
486	        }
487	    }
488	
489	    /**
490	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
491	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
492	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
493	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
494	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
495	     *
496	     * @param ownerFieldsDto the incoming owner payload
497	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
498	     */
499	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
500	        String postcode = ownerFieldsDto.getPostcode();
501	        if (postcode == null) {
502	            return;
503	        }
504	        Region region = Region.forCity(ownerFieldsDto.getCity());
505	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
506	            throw new InvalidPostcodeException(
507	                "postcode " + postcode + " is not valid for the city's region " + region.name());
508	        }
509	    }
510	
511	    /**
512	     * Rejects creating an owner whose whole derived {@code identityKey} (see
513	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
514	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
515	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
516	     * share only their household (same last name and postcode, different telephone) are not caught here but by the
517	     * separate household-duplicate guard (see {@link #requireHouseholdNotDuplicate}).
518	     *
519	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
520	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
521	     */
522	    private void requireUniqueIdentity(Owner owner) {
523	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
524	        boolean inUse = this.clinicService.findAllOwners().stream()
525	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
526	        if (inUse) {
527	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
528	        }
529	    }
530	
531	    /**
532	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared both the hard-duplicate
533	     * guard (see {@link #requireUniqueIdentity}) and the household-duplicate guard (see
534	     * {@link #requireHouseholdNotDuplicate}), so it is still being created; this only records a warning. A declared
535	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
536	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
537	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
538	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
539	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
540	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
541	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
542	     *
543	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
544	     * @param ownerFieldsDto the incoming owner payload
545	     */
546	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
547	        owner.setPossibleDuplicate(false);
548	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
549	            return;
550	        }
551	        String postcode = owner.getPostcode();
552	        if (postcode == null || postcode.isBlank()) {
553	            return;
554	        }
555	        String lastName = owner.getLastName();
556	        String telephone = owner.getTelephone();
557	        for (Owner existing : this.clinicService.findAllOwners()) {
558	            if (lastName.equalsIgnoreCase(existing.getLastName())
559	                && postcode.equals(existing.getPostcode())
560	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
561	                owner.setPossibleDuplicate(true);
562	                owner.setPossibleDuplicateOf(existing.getId());
563	                return;
564	            }
565	        }
566	    }
567	
568	    /**
569	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
570	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
571	     *
572	     * @param city the city of the owner being created
573	     * @throws OwnerCityFullException if the city already contains 50 or more owners
574	     */
575	    private void requireCityHasCapacity(String city) {
576	        long cityOwners = this.clinicService.findAllOwners().stream()
577	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
578	            .count();
579	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
580	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
581	        }
582	    }
583	
584	    /**
585	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
586	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
587	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
588	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
589	     * such owners never match one another as a household.
590	     *
591	     * @param owner the newly mapped owner about to be saved
592	     */
593	    private void assignHouseholdId(Owner owner) {
594	        String postcode = owner.getPostcode();
595	        if (postcode == null || postcode.isBlank()) {
596	            owner.setHouseholdId(null);
597	            return;
598	        }
599	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
600	    }
601	
602	    /**
603	     * Rejects creating an owner that would join an existing household it has not declared. Because the household is
604	     * keyed on the last name and postcode (see {@link #assignHouseholdId}), any existing owner carrying the same
605	     * derived {@code householdId} is a member of the same household. A second such owner is a household duplicate and is
606	     * rejected, unless the payload sets {@code sharesHousehold} to {@code true}, which declares the owner a genuine
607	     * household member and lets the create proceed. An owner with no household ({@code null} householdId, i.e. created
608	     * without a postcode) can never be a household duplicate.
609	     *
610	     * @param owner          the newly mapped owner about to be saved, with its household id already assigned
611	     * @param ownerFieldsDto the incoming owner payload
612	     * @throws DuplicateOwnerException if an existing owner already belongs to this household and the create did not
613	     *                                 declare {@code sharesHousehold}
614	     */
615	    private void requireHouseholdNotDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
616	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
617	            return;
618	        }
619	        String householdId = owner.getHouseholdId();
620	        if (householdId == null) {
621	            return;
622	        }
623	        boolean sharedByExisting = this.clinicService.findAllOwners().stream()
624	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
625	        if (sharedByExisting) {
626	            throw new DuplicateOwnerException("an owner in the same household already exists");
627	        }
628	    }
629	
630	    /**
631	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
632	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
633	     * household is counted as a household of one.
634	     *
635	     * @param owner the owner whose household size should be resolved
636	     */
637	    private void populateHouseholdMemberCount(Owner owner) {
638	        String householdId = owner.getHouseholdId();
639	        if (householdId == null) {
640	            owner.setHouseholdMemberCount(1);
641	            return;
642	        }
643	        long members = this.clinicService.findAllOwners().stream()
644	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
645	            .count();
646	        owner.setHouseholdMemberCount((int) members);
647	    }
648	
649	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
650	    @Override
651	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
652	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
653	        if (currentOwner == null) {
654	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
655	        }
656	        validatePostcode(ownerFieldsDto);
657	        currentOwner.setAddress(ownerFieldsDto.getAddress());
658	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
659	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
660	        currentOwner.setCity(ownerFieldsDto.getCity());
661	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
662	        currentOwner.setLastName(ownerFieldsDto.getLastName());
663	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
664	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
665	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
666	        this.clinicService.saveOwner(currentOwner);
667	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
668	    }
669	
670	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
671	    @Transactional
672	    @Override
673	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
674	        Owner owner = this.clinicService.findOwnerById(ownerId);
675	        if (owner == null) {
676	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
677	        }
678	        this.clinicService.deleteOwner(owner);
679	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
680	    }
681	
682	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
683	    @Override
684	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
685	        Owner owner = this.clinicService.findOwnerById(ownerId);
686	        if (owner == null) {
687	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
688	        }
689	        HttpHeaders headers = new HttpHeaders();
690	        Pet pet = petMapper.toPet(petFieldsDto);
691	        owner.setId(ownerId);
692	        pet.setOwner(owner);
693	        pet.getType().setName(null);
694	        this.clinicService.savePet(pet);
695	        PetDto petDto = petMapper.toPetDto(pet);
696	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
697	            .buildAndExpand(pet.getId()).toUri());
698	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
699	    }
700	
701	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
702	    @Override
703	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
704	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
705	        if (currentOwner != null) {
706	            Pet currentPet = this.clinicService.findPetById(petId);
707	            if (currentPet != null) {
708	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
709	                currentPet.setName(petFieldsDto.getName());
710	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
711	                this.clinicService.savePet(currentPet);
712	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
713	            }
714	        }
715	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
716	    }
717	
718	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
719	    @Override
720	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
721	        HttpHeaders headers = new HttpHeaders();
722	        Visit visit = visitMapper.toVisit(visitFieldsDto);
723	        Pet pet = new Pet();
724	        pet.setId(petId);
725	        visit.setPet(pet);
726	        this.clinicService.saveVisit(visit);
727	        VisitDto visitDto = visitMapper.toVisitDto(visit);
728	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
729	            .buildAndExpand(visit.getId()).toUri());
730	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
731	    }
732	
733	
734	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
735	    @Override
736	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
737	        Owner owner = this.clinicService.findOwnerById(ownerId);
738	        if (owner != null) {
739	            Pet pet = owner.getPet(petId);
740	            if (pet != null) {
741	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
742	            }
743	        }
744	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
745	    }
746	}
